import {seasonHash,seasonDefaults,generateSchedule,validateSchedule,createSeason,seasonStandings,qualifySeason,startPlayoffs,advanceSeasonBracket,simulateSeasonGame,recordSeasonResult,seasonCareer} from './season.js';
// Metadata stays small. Full play logs are loaded only for live games or an opened gamecast.
let league=null,leagueArchive=[],leagueTemplates=[],seasonDraft=null,seasonTab='scoreboard',leagueSpeed=10,leagueBusy=false,leaguePaused=false,leagueInstant=false,leagueLive=new Map(),leagueWatch=null,leaguePreviewMatchup=null,leagueFilter='',leagueDivision='',leagueTier='',leagueSort='rank',leagueLayout='grid',leagueBoardPhase='auto',leagueBoardRound=0,leaguePage=0,seasonSetupPage=0,leagueMessage='',leagueProgress='',careerTeam='',favorites=new Set(),excludedCareerSeasons=new Set(),seedDraft=null;
const seasonReady=new Promise((resolve,reject)=>{const req=indexedDB.open('friday-night-seasons',1);req.onupgradeneeded=()=>{for(const name of ['seasons','results','templates','prefs'])req.result.createObjectStore(name,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function seasonDB(store,action,value){const database=await seasonReady;return new Promise((resolve,reject)=>{const tx=database.transaction(store,action==='get'||action==='getAll'?'readonly':'readwrite'),req=action==='getAll'?tx.objectStore(store).getAll():tx.objectStore(store)[action](value);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage transaction aborted.'));});}
async function persistLeague(full){const database=await seasonReady;return new Promise((resolve,reject)=>{const tx=database.transaction(full?['seasons','results']:['seasons'],'readwrite');tx.objectStore('seasons').put(league);if(full)tx.objectStore('results').put(storedSeasonResult(full));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage is full.'));});}
// Logos live in the immutable season roster, not in every game's stored result.
function storedSeasonResult(full){return {...full,seasonRosterLogos:true,teams:full.teams.map(t=>{const {logo,...team}=t;return team;})};}
function hydrateSeasonResult(full){if(full?.seasonRosterLogos)full.teams=full.teams.map(t=>({...t,logo:leagueTeam(t.id)?.logo}));return full;}
// The scoreboard only needs score/clock frames. Full plays load for one watched game.
function liveSeasonSummary(full){return {teams:full.teams.map(t=>({id:t.id})),score:full.score,seed:full.seed,ot:full.ot,events:full.events.map(e=>({after:{q:e.after.q,time:e.after.time,score:e.after.score}}))};}
async function restoreLeagueLive(){leagueLive.clear();for(const f of league.games.filter(g=>g.status==='live')){const full=await seasonDB('results','get',`${league.id}:${f.id}`);if(full)leagueLive.set(f.id,liveSeasonSummary(full));await seasonYield();}}
async function prepareSeasonLogos(){for(const t of league?.teams||[]){if(!t.logo||displayLogoCache.has(t.logo))continue;try{const im=await loadImage(t.logo),c=document.createElement('canvas'),scale=Math.min(1,128/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);displayLogoCache.set(t.logo,c.toDataURL('image/png'));c.width=c.height=1;}catch{displayLogoCache.set(t.logo,t.logo);}await seasonYield();}}
const seasonYield=()=>new Promise(r=>setTimeout(r,0));
const leagueTeam=id=>league?.teams.find(t=>t.id===id);
const seasonOption=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
function seasonButton(action,label,cls='',disabled=false){return `<button data-season-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;}
function newSeasonDraft(reuse=false){const previous=league;seasonDraft={state:reuse?leagueState(previous):selectedState,name:reuse?previous.name:'',seed:randomSeed(),teams:reuse?structuredClone(previous.teams):[],settings:reuse?structuredClone(previous.settings):seasonDefaults(Math.max(8,stateTeams().length)),schedule:[],divisions:reuse?[...new Set(previous.teams.map(t=>t.division).filter(Boolean))].join(', '):'',tiers:reuse?[...new Set(previous.teams.map(t=>t.tier).filter(Boolean))].join(', '):'',savedSelection:new Set()};seasonSetupPage=0;leagueMessage='';seasonTab='setup';}
function renderSeason(){if(!$('season'))return;$('season').classList.toggle('simple-active',seasonTab==='simple-setup'||(league?.settings.simple&&!simpleExpanded&&['scoreboard','bracket'].includes(seasonTab)));if(!seasonDraft&&!league)newSeasonDraft();$('season').innerHTML=`<div class="season-hero"><div><div class="eyebrow">ONE LEAGUE. ONE BRACKET. ONE CHAMPION.</div><h1>SEASON <em>MODE</em></h1><p>${league&&seasonTab!=='setup'?esc(league.name)+' · '+league.teams.length+' schools · '+(league.status==='complete'?'Season complete':league.status==='playoffs'?'Playoff round '+league.rounds.length:league.status==='seeding'?'Playoff seeding':'Week '+league.week):'Create the league. Let football decide.'}</p></div><div class="actions">${seasonButton('simple','SIMPLE','primary',leagueBusy)}${seasonButton('new','Start new season','ghost',leagueBusy)}${seasonButton('reset-stats','Reset Season Stats','small danger',leagueBusy)}${league?seasonButton('reuse','Reuse previous league','ghost',leagueBusy):''}</div></div>${league?.settings.simple&&simpleExpanded?'<button data-simple="return" class="primary">← BACK TO SIMPLE</button>':''}<div class="season-tabs">${[['scoreboard','League scoreboard'],['standings','Standings'],['bracket','Unified playoffs'],['career','Team history'],['archive','Season archive'],['setup','League setup']].map(([key,label])=>`<button data-season-tab="${key}" class="${seasonTab===key?'active':''}">${label}</button>`).join('')}</div><div id="season-message" role="status">${leagueMessage?`<p class="season-notice">${esc(leagueMessage)}</p>`:''}</div>${leagueBusy?`<div class="season-progress" role="status"><span class="dot"></span> ${esc(leagueProgress||'Simulating…')} ${seasonButton('pause',leaguePaused?'▶ Resume league':'Ⅱ Pause league','small')} ${seasonButton('fastfinish','Finish this batch instantly','small')}</div>`:''}<div id="season-body"></div>`;if(seasonTab==='simple-setup')renderSimpleSetup();else if(seasonTab==='setup')renderSeasonSetup();else if(seasonTab==='archive')renderSeasonArchive();else if(seasonTab==='career')renderSeasonCareer();else if(!league)$('season-body').innerHTML='<div class="panel empty">Create a league in League setup to get started.</div>';else if(league.settings.simple&&!simpleExpanded&&['scoreboard','bracket'].includes(seasonTab))renderSimpleSeason();else if(seasonTab==='standings')renderSeasonStandings();else if(seasonTab==='bracket')renderSeasonBracket();else if(league.settings.simple&&!simpleExpanded)renderSimpleSeason();else renderLeagueScoreboard();}
function draftSettings(){return `<div class="settings-grid"><div><label>Season name</label><input data-draft="name" value="${esc(seasonDraft.name)}" placeholder="Friday Night League"></div><div><label>Seed · reproducible results</label><input data-draft="seed" type="number" min="0" max="4294967295" value="${seasonDraft.seed}"></div>${[['games','Games per team'],['weeks','Number of weeks'],['playoffTeams','Playoff teams']].map(([k,l])=>`<div><label>${l}</label><input data-setting="${k}" type="number" min="${k==='playoffTeams'?2:1}" value="${seasonDraft.settings[k]}"></div>`).join('')}<div><label>Schedule priorities</label><select data-setting="format">${[['balanced','Balanced / cross-league'],['division','Prioritize divisions'],['tier','Prioritize classifications']].map(([v,l])=>seasonOption(v,l,seasonDraft.settings.format)).join('')}</select></div><div><label>Playoff qualification</label><select data-setting="qualification">${[['overall','Best overall records'],['division','Division winners + at-large'],['tier','Classification leaders + at-large'],['manual','Manual selection']].map(([v,l])=>seasonOption(v,l,seasonDraft.settings.qualification)).join('')}</select></div><div><label>Tiebreak preference</label><select data-setting="tiebreak">${seasonOption('differential','Point differential, then strength of schedule',seasonDraft.settings.tiebreak)}${seasonOption('sos','Strength of schedule, then point differential',seasonDraft.settings.tiebreak)}</select></div><div><label>Division names · comma separated</label><input data-draft="divisions" value="${esc(seasonDraft.divisions)}" placeholder="North, South, East, West"></div><div><label>Classification names · comma separated</label><input data-draft="tiers" value="${esc(seasonDraft.tiers)}" placeholder="1A, 2A, 3A, 4A"></div><div><label>Weather</label><select data-game-setting="weather">${['clear','rain','wind','snow'].map(v=>seasonOption(v,v,seasonDraft.settings.gameOptions.weather)).join('')}</select></div><div><label>Overtime starting yard line</label><select data-game-setting="otStart">${[10,20,25].map(v=>seasonOption(String(v),'Opponent '+v,String(seasonDraft.settings.gameOptions.otStart))).join('')}</select></div><label class="inline"><input data-setting="allowDouble" type="checkbox" ${seasonDraft.settings.allowDouble?'checked':''}>Allow multiple games per week (custom schedule)</label><label class="inline"><input data-game-setting="neutral" type="checkbox" ${seasonDraft.settings.gameOptions.neutral?'checked':''}>Neutral sites</label></div>`;}
function groupNames(key){return seasonDraft[key].split(',').map(x=>x.trim()).filter(Boolean);}
function renderSeasonSetup(){if(!seasonDraft)newSeasonDraft();const d=seasonDraft;const start=seasonSetupPage*24,teams=d.teams.slice(start,start+24);$('season-body').innerHTML=`<div class="panel season-section"><div class="panel-head"><h3>01 / ${esc(stateName(selectedState).toUpperCase())} LEAGUE</h3><span class="pill">${d.teams.length} TEAMS</span></div><div class="actions">${seasonButton('add-saved','Add all '+stateName(selectedState)+' teams')}${seasonButton('select-teams','SELECT TEAMS','primary')}${seasonButton('auto','AUTO SETUP EVERYTHING','primary')}${seasonButton('add-team','+ Create a school')}</div><p class="help">Tap Select Teams to choose schools from a logo grid. Selected cards turn green.</p><div class="season-generate"><div><label>Generate fictional schools</label><input id="fictional-count" type="number" min="1" value="8"></div><div><label>Manual rating for new schools</label><input id="fictional-rating" type="number" min="1" max="99" value="75"></div>${seasonButton('fictional','Add schools')}</div><p class="help">No fixed team cap. Large leagues use more storage and take longer. Generated schools share your rating until you edit it.</p><div class="table-wrap"><table class="season-team-editor"><thead><tr><th>School / rating</th><th>Division</th><th>Classification</th><th></th></tr></thead><tbody>${teams.map(t=>`<tr><td><div class="mini-school">${logo(t)}<div>${esc(t.name)}<input aria-label="${esc(t.name)} rating" data-team-rating="${esc(t.id)}" type="number" min="1" max="99" value="${t.overall}"></div></div></td>${[['division','divisions'],['tier','tiers']].map(([key,list])=>`<td><select aria-label="${esc(t.name)} ${key}" data-team-group="${key}" data-team-id="${esc(t.id)}">${seasonOption('','None',t[key])}${[...new Set([...groupNames(list),t[key]].filter(Boolean))].map(v=>seasonOption(v,v,t[key])).join('')}</select></td>`).join('')}<td>${seasonButton('remove:'+t.id,'Remove','small ghost')}</td></tr>`).join('')}</tbody></table></div>${d.teams.length>24?`<div class="history-pagination">${seasonButton('draft-prev','← Previous','small',start===0)}<span>Page ${seasonSetupPage+1} / ${Math.ceil(d.teams.length/24)}</span>${seasonButton('draft-next','Next →','small',start+24>=d.teams.length)}</div>`:''}</div><div class="panel season-section"><h3>02 / YOUR FORMAT</h3>${draftSettings()}<div class="actions">${seasonButton('assign','Auto assign groups')}${seasonButton('regenerate','Generate / regenerate schedule')}${seasonButton('adjust','Auto adjust schedule','ghost')}${seasonButton('empty-schedule','Build a custom schedule','ghost')}</div><p class="help">Standings: win percentage → head-to-head mini-league when all tied teams met → division percentage for teams in the same division → your preference → seeded draw. Classification never boosts ratings. All teams feed into one championship.</p></div><div class="panel season-section"><div class="panel-head"><h3>03 / SCHEDULE</h3><span>${d.schedule.length} games</span></div><div class="actions">${seasonButton('add-fixture','+ Add matchup')}${seasonButton('template','Save league template')}</div><div id="schedule-editor"></div><div class="actions">${seasonButton('launch','START SEASON →','primary')}</div><p class="help">Every team must have the requested game count. Editing a schedule is available before kickoff. Regular-season games and playoff games are recorded separately from exhibitions.</p></div><div class="panel season-section"><h3>SAVED LEAGUE TEMPLATES</h3>${leagueTemplates.filter(t=>leagueState(t)===selectedState).map(t=>`<div class="template-row"><span>${esc(t.name)} · ${t.teams.length} teams</span>${seasonButton('template-load:'+t.id,'Load','small')}${seasonButton('template-delete:'+t.id,'Delete','small ghost')}</div>`).join('')||'<p class="help">Save a format, teams, groups, ratings, and schedule for later.</p>'}</div>`;renderScheduleEditor();}
// A full-screen, transactional picker: Cancel leaves the league and schedule untouched.
function openSeasonTeamPicker(onDone=null){
 const d=seasonDraft,existing=new Map(d.teams.map(t=>[t.id,t]));
 const schools=[...new Map([...stateTeams(),...d.teams].map(t=>[t.id,t])).values()].sort((a,b)=>a.name.localeCompare(b.name));
 const selected=new Set(existing.keys());
 const dialog=document.createElement('dialog');dialog.id='season-team-picker';dialog.className='season-team-picker';dialog.setAttribute('aria-labelledby','picker-title');
 dialog.innerHTML=`<div class="picker-shell"><header class="picker-header"><div><div class="eyebrow">${esc(stateName(selectedState))} / SEASON MODE</div><h2 id="picker-title">SELECT YOUR TEAMS</h2><p>Tap a school to check it. Green means it’s in your league.</p></div><button type="button" id="picker-cancel" class="ghost">Cancel</button></header><div class="picker-tools"><input id="picker-search" type="search" placeholder="Search schools or mascots…" aria-label="Search schools or mascots"><div class="actions"><button type="button" id="picker-all">Select all shown</button><button type="button" id="picker-clear" class="ghost">Clear all</button><label class="inline"><input id="picker-selected" type="checkbox">Selected only</label></div></div><div class="picker-scroll"><div class="picker-grid">${schools.map(t=>`<label class="picker-card ${selected.has(t.id)?'is-selected':''}" data-picker-id="${esc(t.id)}"><input type="checkbox" data-picker-check="${esc(t.id)}" aria-label="Select ${esc(t.name)}" ${selected.has(t.id)?'checked':''}>${logo(t)}<strong>${esc(t.name)}</strong><small>${esc(t.mascot||'')} · ${t.overall} OVR</small></label>`).join('')}</div><p id="picker-empty" class="empty" hidden>No matching schools. Try a different search.</p></div><footer class="picker-footer"><div><strong id="picker-count" role="status" aria-live="polite"></strong><small id="picker-shown"></small></div><button type="button" id="picker-done" class="primary">USE SELECTED TEAMS →</button></footer></div>`;
 document.body.append(dialog);document.body.classList.add('team-picker-open');
 const search=dialog.querySelector('#picker-search'),only=dialog.querySelector('#picker-selected'),cards=[...dialog.querySelectorAll('.picker-card')];
 const matches=t=>(!only.checked||selected.has(t.id))&&`${t.name} ${t.mascot||''}`.toLowerCase().includes(search.value.trim().toLowerCase());
 function refresh(){let shown=0;cards.forEach((card,i)=>{const t=schools[i],checked=selected.has(t.id);card.hidden=!matches(t);if(!card.hidden)shown++;card.classList.toggle('is-selected',checked);card.querySelector('input').checked=checked;});dialog.querySelector('#picker-count').textContent=`${selected.size} teams selected`;dialog.querySelector('#picker-shown').textContent=`${shown} of ${schools.length} schools shown`;const empty=dialog.querySelector('#picker-empty');empty.hidden=shown>0;empty.textContent=schools.length?'No matching schools. Try a different search or turn off Selected only.':'No schools saved in this state yet. Return to League setup to create a school.';}
 search.oninput=refresh;only.onchange=refresh;
 dialog.onchange=e=>{const id=e.target.dataset.pickerCheck;if(!id)return;if(e.target.checked)selected.add(id);else selected.delete(id);refresh();};
 dialog.querySelector('#picker-all').onclick=()=>{schools.filter(matches).forEach(t=>selected.add(t.id));refresh();};
 dialog.querySelector('#picker-clear').onclick=()=>{selected.clear();refresh();};
 dialog.querySelector('#picker-cancel').onclick=()=>dialog.close();
 dialog.querySelector('#picker-done').onclick=()=>{if(onDone&&selected.size<2){toast('Select at least two schools.');return;}const changed=selected.size!==existing.size||[...selected].some(id=>!existing.has(id));if(changed){d.teams=[...d.teams.filter(t=>selected.has(t.id)),...schools.filter(t=>selected.has(t.id)&&!existing.has(t.id)).map(t=>({...structuredClone(t),division:'',tier:''}))];d.schedule=[];seasonSetupPage=0;leagueMessage='Team selection updated. Use Auto Setup or Generate schedule to schedule your league.';}dialog.close();if(onDone)onDone();else renderSeason();};
 dialog.onclose=()=>{document.body.classList.remove('team-picker-open');dialog.remove();document.querySelector('[data-season-action="select-teams"]')?.focus();};
 refresh();dialog.showModal();dialog.querySelector('#picker-cancel').focus();
}
let draftWeek=1;
function renderScheduleEditor(){if(!$('schedule-editor'))return;const d=seasonDraft;draftWeek=Math.min(Math.max(1,draftWeek),+d.settings.weeks||1);const opt=selected=>d.teams.map(t=>seasonOption(t.id,t.name,selected)).join('');$('schedule-editor').innerHTML=`<div class="filters"><label>Week <select id="draft-week">${Array.from({length:+d.settings.weeks||1},(_,i)=>seasonOption(String(i+1),'Week '+(i+1),String(draftWeek))).join('')}</select></label><span class="help">Choose any week to edit its matchups.</span></div>${d.schedule.filter(g=>g.week===draftWeek).map(g=>`<div class="fixture-editor"><select aria-label="Away team" data-fixture="${g.id}" data-field="away">${opt(g.away)}</select><span>at</span><select aria-label="Home team" data-fixture="${g.id}" data-field="home">${opt(g.home)}</select><input aria-label="Week" type="number" min="1" data-fixture="${g.id}" data-field="week" value="${g.week}">${seasonButton('fixture-remove:'+g.id,'✕','small ghost')}</div>`).join('')||'<p class="help">No games in this week. Teams have a bye.</p>'}`;}
function leagueControls(){const regular=league.status==='regular';return `<div class="league-controls"><div class="actions">${seasonButton('sim-week','SIM CURRENT WEEK','primary',leagueBusy||!regular)}${seasonButton('sim-next','SIM NEXT WEEK','',leagueBusy||!regular)}${seasonButton('sim-regular','SIM REGULAR SEASON','',leagueBusy||!regular)}${seasonButton('sim-round','SIM PLAYOFF ROUND','',leagueBusy||!['playoffs','seeding'].includes(league.status))}${seasonButton('sim-playoffs','SIM PLAYOFFS','',leagueBusy||!['playoffs','seeding'].includes(league.status))}${seasonButton('sim-all','SIM ENTIRE SEASON','primary',leagueBusy||league.status==='complete')}</div><div class="filters"><label>League speed <select id="league-speed">${[1,5,10,25,'instant'].map(v=>seasonOption(String(v),v==='instant'?'INSTANT':v+'×',String(leagueSpeed))).join('')}</select></label><span class="help">Gamecasts stay live while the whole league advances.</span></div></div>`;}
function boardPhase(){return leagueBoardPhase==='auto'?(league.status==='regular'||league.status==='seeding'?'regular':'playoff'):leagueBoardPhase;}
function filteredGames(){return league.games.filter(g=>g.phase===boardPhase()&&(g.phase==='regular'?g.week===league.week:g.round===(leagueBoardRound||league.rounds.length))).filter(g=>[g.away,g.home].some(id=>{const t=leagueTeam(id);return t&&(t.name.toLowerCase().includes(leagueFilter.toLowerCase())||t.mascot.toLowerCase().includes(leagueFilter.toLowerCase()));})).sort((a,b)=>Number([b.away,b.home].some(id=>favorites.has(id)))-Number([a.away,a.home].some(id=>favorites.has(id))));}
function fixtureScore(g){if(g.status==='final')return g.score;if(g.status==='live'){const full=leagueLive.get(g.id);return full?.events[Math.max(0,(g.cursor||0)-1)]?.after.score||[0,0];}return ['—','—'];}
function fixtureClock(g){if(g.status==='final')return g.ot?'FINAL / '+g.ot+' OT':'FINAL';if(g.status==='bye')return 'BYE';if(g.status==='live'){const s=leagueLive.get(g.id)?.events[Math.max(0,(g.cursor||0)-1)]?.after;return s?`${s.q>4?'OT '+(s.q-4):'Q'+s.q+' · '+clock(s.time)}`:'KICKOFF';}return 'UPCOMING';}
function fixtureCard(g,rows){const sc=fixtureScore(g);return `<article class="league-game ${g.status==='live'?'is-live':''}" data-game-card="${g.id}"><div class="game-card-top"><span data-clock>${fixtureClock(g)}</span><small>${g.phase==='regular'?'WEEK '+g.week:'ROUND '+g.round}</small></div>${[g.away,g.home].map((id,i)=>{const t=leagueTeam(id);if(!t)return '<div class="score-school">BYE</div>';const rec=rows.find(r=>r.team.id===id);return `<div class="score-school ${g.winner===id?'winner':''}">${logo(t)}<div><strong>${esc(t.name)}</strong><small>${rec?.w||0}–${rec?.l||0} · ${t.overall} OVR ${favorites.has(id)?'★':''}</small></div><b data-score="${i}">${sc[i]}</b></div>`;}).join('')}<div class="game-card-bottom">${g.status==='bye'?'Advances automatically':seasonButton('watch:'+g.id,g.status==='scheduled'?'Preview matchup':'WATCH GAME ↗','small ghost')}<span>${isUpset(g)?'⚡ UPSET':''}</span></div></article>`;}
function isUpset(g){return g.status==='final'&&leagueTeam(g.winner).overall+10<=leagueTeam(g.winner===g.away?g.home:g.away).overall;}
function renderLeagueScoreboard(){const rows=seasonStandings(league,true),regular=seasonStandings(league),games=filteredGames(),completed=league.games.filter(g=>g.status==='final').length;leaguePage=Math.min(leaguePage,Math.max(0,Math.ceil(games.length/24)-1));$('season-body').innerHTML=`${league.status==='complete'?championBanner():''}${leagueControls()}<div class="league-metrics"><div><small>GAMES FINAL</small><strong>${completed}</strong></div><div><small>UNDEFEATED</small><strong>${regular.filter(r=>r.w>0&&!r.l).length}</strong></div><div><small>TOP OF THE TABLE</small><strong>${esc(regular[0]?.team.name||'—')}</strong></div><div><small>PLAYOFF FIELD</small><strong>${league.settings.playoffTeams} teams</strong></div></div><div class="filters"><input id="league-search" placeholder="Find a school…" aria-label="Find a school" value="${esc(leagueFilter)}"><select id="league-layout">${seasonOption('grid','Scoreboard grid',leagueLayout)}${seasonOption('compact','Compact list',leagueLayout)}</select><select id="league-board-phase">${seasonOption('regular','Regular-season scores',boardPhase())}${seasonOption('playoff','Playoff scores',boardPhase())}</select>${boardPhase()==='regular'?`<select id="league-week">${Array.from({length:league.settings.weeks},(_,i)=>seasonOption(String(i+1),'Week '+(i+1),String(league.week))).join('')}</select>`:`<select id="league-board-round">${league.rounds.map((_,i)=>seasonOption(String(i+1),'Round '+(i+1),String(leagueBoardRound||league.rounds.length))).join('')}</select>`}</div><div id="league-cards" class="league-grid ${leagueLayout==='compact'?'compact':''}">${games.slice(leaguePage*24,leaguePage*24+24).map(g=>fixtureCard(g,rows)).join('')||'<div class="panel empty">No games in this view. Advance the week or change your search.</div>'}</div>${games.length>24?`<div class="history-pagination">${seasonButton('games-prev','← Previous','small',!leaguePage)}<span>${leaguePage*24+1}–${Math.min(games.length,leaguePage*24+24)} of ${games.length} games</span>${seasonButton('games-next','Next →','small',(leaguePage+1)*24>=games.length)}</div>`:''}<div class="two-cols season-section"><div class="panel season-section"><h3>PLAYOFF PICTURE / TOP 5</h3>${regular.slice(0,5).map((r,i)=>`<div class="leader-row"><b>${i+1}</b>${logo(r.team)}<span>${esc(r.team.name)}</span><strong>${r.w}–${r.l}</strong></div>`).join('')}${seasonButton('tab:bracket','View unified bracket →','ghost')}</div><div class="panel season-section"><h3>UPSET WATCH / RECENT FINALS</h3>${league.games.filter(g=>g.status==='final').slice(-6).reverse().map(g=>`<div class="recent-league">${isUpset(g)?'⚡ ':''}${esc(leagueTeam(g.away).name)} ${g.score[0]}–${g.score[1]} ${esc(leagueTeam(g.home).name)} ${seasonButton('watch:'+g.id,'Open','small ghost')}</div>`).join('')||'<p class="help">Kick off a week to see the league take shape.</p>'}</div></div>`;}
function championBanner(){const t=leagueTeam(league.champion),final=league.games.find(g=>g.id===league.rounds.at(-1)[0]),record=seasonStandings(league,true).find(r=>r.team.id===t.id),rows=seasonStandings(league),off=rows.slice().sort((a,b)=>b.pf/(b.played||1)-a.pf/(a.played||1))[0],def=rows.slice().sort((a,b)=>a.pa/(a.played||1)-b.pa/(b.played||1))[0],upsets=league.games.filter(g=>g.status==='final').map(g=>({g,gap:leagueTeam(g.winner===g.away?g.home:g.away).overall-leagueTeam(g.winner).overall})).sort((a,b)=>b.gap-a.gap),run=league.teams.map(t=>({t,w:league.games.filter(g=>g.phase==='playoff'&&g.status==='final'&&g.winner===t.id).length})).sort((a,b)=>b.w-a.w)[0];return `<div class="champion-banner" style="--champ:${t.primary}"><div class="eyebrow">THE LEAGUE HAS ITS CHAMPION</div>${logo(t)}<h2>${esc(t.name.toUpperCase())}</h2><p>${esc(t.mascot)} · ${record.w}–${record.l} · CHAMPIONS</p><strong class="championship-score">${final.score.join(' – ')}</strong><p>${esc(leagueTeam(final.away).name)} vs ${esc(leagueTeam(final.home).name)} · Runner-up: ${esc(leagueTeam(league.runnerUp).name)}</p><div class="actions">${seasonButton('champ-graphic','GENERATE CHAMPIONSHIP GRAPHIC','primary')}${seasonButton('watch:'+final.id,'Championship game / stats')}${seasonButton('runback','RUN IT BACK','primary')}${seasonButton('reuse','START NEW SEASON')}</div><div class="recap-grid"><p><small>BEST REGULAR SEASON</small>${esc(rows[0].team.name)} · ${rows[0].w}–${rows[0].l}</p><p><small>HIGHEST-SCORING OFFENSE</small>${esc(off.team.name)} · ${(off.pf/(off.played||1)).toFixed(1)} PPG</p><p><small>BEST SCORING DEFENSE</small>${esc(def.team.name)} · ${(def.pa/(def.played||1)).toFixed(1)} allowed / game</p><p><small>MOST PLAYOFF WINS</small>${esc(run.t.name)} · ${run.w} wins</p><p><small>BIGGEST RATING UPSET</small>${upsets[0]?.gap>0?esc(leagueTeam(upsets[0].g.winner).name)+' · '+upsets[0].gap+' rating points':'No lower-rated winner'}</p></div></div>`;}
function renderSeasonStandings(){const divisions=[...new Set(league.teams.map(t=>t.division).filter(Boolean))],tiers=[...new Set(league.teams.map(t=>t.tier).filter(Boolean))];let rows=seasonStandings(league);const ranks=new Map(rows.map((r,i)=>[r.team.id,i+1]));rows=rows.filter(r=>(!leagueDivision||r.team.division===leagueDivision)&&(!leagueTier||r.team.tier===leagueTier)&&r.team.name.toLowerCase().includes(leagueFilter.toLowerCase()));if(leagueSort!=='rank')rows.sort((a,b)=>leagueSort==='name'?a.team.name.localeCompare(b.team.name):leagueSort==='power'?(b.team.overall+b.winPct*10)-(a.team.overall+a.winPct*10):b[leagueSort]-a[leagueSort]);let projected=[];try{projected=qualifySeason(league);}catch{}$('season-body').innerHTML=`<div class="filters"><input id="standings-search" aria-label="Search standings" placeholder="Find a school…" value="${esc(leagueFilter)}"><select id="standings-division">${seasonOption('','All divisions',leagueDivision)}${divisions.map(v=>seasonOption(v,v,leagueDivision)).join('')}</select><select id="standings-tier">${seasonOption('','All classifications',leagueTier)}${tiers.map(v=>seasonOption(v,v,leagueTier)).join('')}</select><select id="standings-sort">${[['rank','Official standings'],['name','School name'],['w','Wins'],['winPct','Winning percentage'],['pf','Points scored'],['pa','Points allowed'],['diff','Point differential'],['power','Power index · unofficial']].map(([v,l])=>seasonOption(v,l,leagueSort)).join('')}</select></div><p class="help">Regular-season standings. Power index is rating + 10 × winning percentage; it never controls playoff qualification. “In picture” is provisional until all regular-season games finish.</p><div class="panel table-wrap"><table class="standings-table"><thead><tr><th>#</th><th>School</th><th>W–L</th><th>Win %</th><th>Division / W–L</th><th>Class</th><th>PF</th><th>PA</th><th>+/−</th><th>Streak</th><th>Playoffs</th><th>Follow</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${ranks.get(r.team.id)}</td><td><div class="mini-school">${logo(r.team)}<button data-season-action="team-history:${esc(r.team.id)}" class="ghost">${esc(r.team.name)}</button></div></td><td>${r.w}–${r.l}</td><td>${(r.winPct*100).toFixed(1)}%</td><td>${esc(r.team.division||'—')} / ${r.dw}–${r.dl}</td><td>${esc(r.team.tier||'—')}</td><td>${r.pf}</td><td>${r.pa}</td><td>${r.diff>0?'+':''}${r.diff}</td><td>${r.streak?`${r.streak>0?'W':'L'}${Math.abs(r.streak)}`:'—'}</td><td>${league.seeds.length?(league.seeds.includes(r.team.id)?'Qualified':'Out'):league.settings.qualification==='manual'?'Manual selection':projected.includes(r.team.id)?'In picture':'—'}</td><td>${seasonButton('star:'+r.team.id,favorites.has(r.team.id)?'★':'☆','small ghost')}</td></tr>`).join('')}</tbody></table></div>`;}
function renderSeasonBracket(){if(!league.rounds.length){const finished=league.games.every(g=>g.status==='final');if(!seedDraft){try{seedDraft=qualifySeason(league);}catch(e){leagueMessage=e.message;seedDraft=[];}}$('season-body').innerHTML=`<div class="panel season-section"><div class="eyebrow">ONE UNIFIED FIELD</div><h2>${league.settings.playoffTeams} TEAMS. ONE TROPHY.</h2><p>${finished?'Set the seeds, then lock the bracket.':'Finish the regular season to qualify and seed the playoff field.'}</p>${finished?`<div class="seed-editor">${Array.from({length:+league.settings.playoffTeams},(_,i)=>`<label>Seed ${i+1}<select data-playoff-seed="${i}"><option value="">Choose a team</option>${seasonStandings(league).map(r=>seasonOption(r.team.id,`${r.team.name} (${r.w}–${r.l}) · ${r.team.tier||'Open'}`,seedDraft[i])).join('')}</select></label>`).join('')}</div><div class="actions">${seasonButton('lock-bracket','LOCK SEEDS / START PLAYOFFS','primary')}${seasonButton('auto-seeds','Reset automatic seeds')}</div>`:leagueControls()}<p class="help">Highest seeds receive first-round byes when necessary. Every school can face every classification. Higher seed hosts; the final is neutral. Seeds become fixed when the bracket starts.</p></div>`;return;}const rows=seasonStandings(league,true);$('season-body').innerHTML=`${league.status==='complete'?championBanner():leagueControls()}<div class="bracket-scroll"><div class="season-bracket">${league.rounds.map((ids,i)=>`<div class="bracket-round"><h3>${ids.length===1?'CHAMPIONSHIP':ids.length===2?'SEMIFINALS':ids.length===4?'QUARTERFINALS':'ROUND '+(i+1)}</h3>${ids.map(id=>{const g=league.games.find(x=>x.id===id);return `<div class="bracket-match"><small>${[g.away,g.home].filter(Boolean).map(id=>'#'+(league.seeds.indexOf(id)+1)).join(' vs ')}</small>${fixtureCard(g,rows)}</div>`;}).join('')}</div>`).join('')}${league.status!=='complete'?'<div class="bracket-round"><h3>NEXT ROUND</h3><div class="panel empty">Winners advance here automatically.</div></div>':''}</div></div>`;}
function renderSeasonArchive(){$('season-body').innerHTML=`<div class="panel season-section"><h2>EVERY SEASON HAS A STORY.</h2><p class="help">Progress and full play histories are stored on this browser. Opening an archive never resimulates a result.</p>${leagueArchive.filter(s=>leagueState(s)===selectedState).sort((a,b)=>b.created.localeCompare(a.created)).map(s=>`<div class="archive-season"><div><strong>${esc(s.name)}</strong><small>${new Date(s.created).toLocaleDateString()} · ${s.teams.length} teams · ${s.status==='complete'?'CHAMPION: '+esc(s.teams.find(t=>t.id===s.champion)?.name):'In progress'}</small></div>${seasonButton('archive:'+s.id,'Open season','small',leagueBusy)}</div>`).join('')||'<div class="empty">Your seasons will appear here.</div>'}</div>`;}
function currentSeasonCareers(){return seasonCareer(leagueArchive.filter(s=>leagueState(s)===selectedState&&!excludedCareerSeasons.has(s.id)));}
function renderSeasonCareer(){const careers=currentSeasonCareers(),ordered=careers.slice().sort((a,b)=>b.titles-a.titles||b.w-a.w),selected=careers.find(c=>c.team.id===careerTeam);$('season-body').innerHTML=`<div class="panel season-section"><div class="eyebrow">CAREER RECORDS / COMPLETED SEASONS ONLY</div><h2>TEAM HISTORY</h2><div class="actions">${seasonButton('reset-stats','Reset Season Stats','small danger',leagueBusy)}</div><p class="help">Reset clears career totals and leaderboards for a fresh start. Existing seasons stay in the archive, with their original standings and scores.</p><p class="help">Season games are counted once, from completed season archives. Exhibition records remain in Saved games. Playoff byes are appearances, never wins.</p><label for="career-team">Choose a school</label><select id="career-team"><option value="">Select a school…</option>${careers.sort((a,b)=>a.team.name.localeCompare(b.team.name)).map(c=>seasonOption(c.team.id,c.team.name,careerTeam)).join('')}</select>${selected?careerDetail(selected):'<div class="empty">Select a team to explore its seasons, championships, and all-time records.</div>'}</div><div class="two-cols">${[['titles','CHAMPIONSHIPS'],['w','ALL-TIME WINS'],['appearances','PLAYOFF APPEARANCES'],['undefeated','UNDEFEATED SEASONS']].map(([key,title])=>`<div class="panel season-section"><h3>${title}</h3>${ordered.slice().sort((a,b)=>b[key]-a[key]).slice(0,10).map(c=>`<div class="leader-row">${logo(c.team)}<span>${esc(c.team.name)}</span><strong>${c[key]}</strong></div>`).join('')||'<p class="help">Complete a season to start the record book.</p>'}</div>`).join('')}</div>`;}
function careerDetail(c){const pct=(w,l)=>(w+l?100*w/(w+l):0).toFixed(1)+'%';return `<div class="record-summary">${logo(c.team)}<div><h2>${esc(c.team.name)}</h2><span>${c.titles} championships · ${c.w}–${c.l} all time</span></div></div><div class="recap-grid">${[['Total games',c.w+c.l],['Win percentage',pct(c.w,c.l)],['Points scored / allowed',c.pf+' / '+c.pa],['Regular season',`${c.regularW}–${c.regularL} (${pct(c.regularW,c.regularL)})`],['Division titles',c.divisionTitles],['Playoffs',`${c.playoffW}–${c.playoffL} (${pct(c.playoffW,c.playoffL)})`],['Playoff appearances',c.appearances],['Quarterfinals / Semifinals',c.quarters+' / '+c.semis],['Championship appearances',c.finals],['Runner-up finishes',c.runnerUp],['Undefeated seasons',c.undefeated],['Best / worst season',`${c.best.w}–${c.best.l} / ${c.worst.w}–${c.worst.l}`],['Longest winning streak',c.longestStreak],['Most points in a game',c.maxPoints],['Biggest victory',c.biggestWin+' points'],['Biggest rating upset',c.biggestUpset+' points']].map(([l,v])=>`<p><small>${l}</small><strong>${v}</strong></p>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Season</th><th>Overall</th><th>Regular</th><th>Playoffs</th><th>Finish</th></tr></thead><tbody>${c.seasons.map(s=>`<tr><td>${seasonButton('archive:'+s.seasonId,esc(s.name),'ghost',leagueBusy)}</td><td>${s.w}–${s.l}</td><td>${s.regularW}–${s.regularL}</td><td>${s.playoffW}–${s.playoffL}</td><td>${s.finish}</td></tr>`).join('')}</tbody></table></div>`;}
async function saveSeasonArchive(){await persistLeague();const index=leagueArchive.findIndex(s=>s.id===league.id);if(index<0)leagueArchive.push(league);else leagueArchive[index]=league;leagueArchive.sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0);}
async function launchSeason(){const d=seasonDraft;if(d.teams.some(t=>teamState(t)!==selectedState))throw new Error('Choose teams from the selected state.');if(d.teams.length<2)throw new Error('Add at least two schools.');if(d.teams.some(t=>!Number.isInteger(t.overall)||t.overall<1||t.overall>99))throw new Error('Every school needs a whole-number rating from 1–99.');const count=+d.settings.playoffTeams;if(!Number.isInteger(count)||count<2||count>d.teams.length)throw new Error('Playoff teams must be between two and the league size.');const errors=validateSchedule(d.teams,d.settings,d.schedule);if(errors.length)throw new Error(errors.slice(0,5).join(' '));if(d.settings.qualification==='division'||d.settings.qualification==='tier'){const key=d.settings.qualification==='division'?'division':'tier';if(new Set(d.teams.map(t=>t[key]).filter(Boolean)).size>count)throw new Error('More group winners than playoff places. Increase the playoff size or choose overall qualification.');}league={version:1,state:selectedState,id:crypto.randomUUID(),name:d.name.trim()||'Friday Night League',seed:Number(d.seed)>>>0,created:new Date().toISOString(),teams:structuredClone(d.teams),settings:structuredClone(d.settings),games:structuredClone(d.schedule),rounds:[],seeds:[],week:1,status:'regular',champion:null};detachSeasonWatch();leagueLive.clear();seedDraft=null;leagueFilter='';leagueBoardPhase='auto';leagueBoardRound=0;leaguePage=0;await saveSeasonArchive();await seasonDB('prefs','put',{id:'active',value:league.id});await prepareSeasonLogos();seasonTab='scoreboard';leagueMessage='Season ready. Ratings are locked for this season.';renderSeason();}
function generateDraft(adjust=false){const d=seasonDraft;if(adjust){if(d.teams.length%2&&d.settings.games%2)d.settings.games++;d.settings.weeks=Math.max(d.settings.weeks,d.settings.games+(d.teams.length%2));d.settings.playoffTeams=Math.max(2,Math.min(d.teams.length,d.settings.playoffTeams));}const result=generateSchedule(d.teams,d.settings,d.seed);if(result.requiredWeeks>d.settings.weeks){if(adjust)d.settings.weeks=result.requiredWeeks;else throw new Error(`This schedule requires ${result.requiredWeeks} weeks. Click Auto adjust schedule to apply that change.`);}d.schedule=result.games;leagueMessage=`${result.games.length} games scheduled. Every team plays ${d.settings.games} games. ${d.settings.games>d.teams.length-1?'Repeat opponents are necessary for this game count.':''}`;}
async function runLeagueAction(action){if(!league||leagueBusy)return;const perform=async()=>{try{localStorage.setItem('friday-night-view','season');}catch{}leagueBusy=true;leaguePaused=false;leagueInstant=['sim-regular','sim-playoffs','sim-all'].includes(action)||leagueSpeed==='instant';leagueMessage='';try{await prepareSeasonLogos();if(currentView==='season')renderSeason();
 if(action==='sim-week'||action==='sim-next'){const week=league.week;await playLeagueBatch(league.games.filter(g=>g.phase==='regular'&&g.week===week&&!['final','bye'].includes(g.status)));if(action==='sim-next')league.week=Math.min(league.settings.weeks,week+1);}
 else if(action==='sim-regular'||action==='sim-all'){const remaining=league.games.filter(g=>g.phase==='regular'&&g.status!=='final');await playLeagueBatch(remaining);league.week=league.settings.weeks;}
 if(league.status==='regular'&&league.games.filter(g=>g.phase==='regular').every(g=>g.status==='final')){seedDraft=null;if(league.settings.qualification==='manual'){league.status='seeding';seasonTab='bracket';leagueMessage='Regular season complete. Select your playoff teams and seeds to continue.';}else if(action==='sim-all'){startPlayoffs(league);await saveSeasonArchive();}else{league.status='seeding';seedDraft=qualifySeason(league);seasonTab='bracket';leagueMessage='Regular season complete. Review or edit the seeds before starting the unified playoffs.';}}
 if(['sim-round','sim-playoffs','sim-all'].includes(action)&&league.status==='seeding'&&league.settings.qualification!=='manual'){startPlayoffs(league,seedDraft||qualifySeason(league));await saveSeasonArchive();}
 if(['sim-round','sim-playoffs','sim-all'].includes(action)&&league.status==='playoffs'){do{const current=league.rounds.at(-1).map(id=>league.games.find(g=>g.id===id)).filter(g=>!['final','bye'].includes(g.status));await playLeagueBatch(current);advanceSeasonBracket(league);await saveSeasonArchive();if(action==='sim-round')break;}while(league.status==='playoffs');}
 await saveSeasonArchive();if(league.status==='complete'){seasonTab='scoreboard';if(['season','gamecast','log','stats'].includes(currentView)){detachSeasonWatch();view('season');}}
 }catch(e){try{const saved=await seasonDB('seasons','get',league.id);if(saved){league=saved;await restoreLeagueLive();}}catch{}leagueMessage='Simulation paused: '+e.message;toast(leagueMessage);}finally{leagueBusy=false;leaguePaused=false;leagueProgress='';if(currentView==='season')renderSeason();if(leagueWatch)syncSeasonWatch();}};
 if(navigator.locks)await navigator.locks.request('friday-night-season-simulation',{ifAvailable:true},async lock=>{if(!lock){toast('A season is running in another tab. Finish it there first.');return;}const latest=await seasonDB('seasons','get',league.id);if(latest)league=latest;await perform();});else await perform();}
async function playLeagueBatch(fixtures){let prepared=0,lastPaint=0;const batch=[...fixtures];for(const f of batch){while(leaguePaused&&!leagueInstant)await new Promise(r=>setTimeout(r,100));let full=await seasonDB('results','get',`${league.id}:${f.id}`);if(!full)full=simulateSeasonGame(league,f);if(!full)continue;if(leagueWatch?.seasonId===league.id&&leagueWatch.fixtureId===f.id){game=hydrateSeasonResult(full);cursor=f.cursor||0;}
 if(leagueInstant){recordSeasonResult(league,f.id,full);leagueLive.delete(f.id);await persistLeague(full);}else{f.status='live';f.cursor=f.cursor||0;leagueLive.set(f.id,liveSeasonSummary(full));await persistLeague(full);}prepared++;leagueProgress=`${leagueInstant?'Completed':'Preparing'} ${prepared} / ${batch.length} games`;if(performance.now()-lastPaint>100){updateLeagueCards();lastPaint=performance.now();}await seasonYield();}
 if(!leagueInstant&&batch.some(f=>f.status==='live')){if(currentView==='season')renderSeason();let lastSave=performance.now();while(batch.some(f=>f.status==='live')){await new Promise(r=>setTimeout(r,100));if(leaguePaused&&!leagueInstant)continue;let newFinal=false;for(const f of batch.filter(f=>f.status==='live')){const full=leagueLive.get(f.id);f.cursor=leagueInstant||leagueSpeed==='instant'?full.events.length:Math.min(full.events.length,(f.cursor||0)+Math.max(1,Math.ceil(Number(leagueSpeed)/2)));if(f.cursor===full.events.length){recordSeasonResult(league,f.id,full);leagueLive.delete(f.id);newFinal=true;}}
 leagueProgress=`${batch.filter(f=>f.status==='final').length} / ${batch.length} games final`;if(newFinal&&currentView==='season')renderSeason();else updateLeagueCards();if(leagueWatch)syncSeasonWatch();if(performance.now()-lastSave>1000){await persistLeague();lastSave=performance.now();}}
 }await saveSeasonArchive();if(currentView==='season')renderSeason();}
function updateLeagueCards(){if(currentView!=='season')return;if($('simple-status'))$('simple-status').textContent=leagueProgress;document.querySelectorAll('[data-game-card]').forEach(card=>{const f=league.games.find(g=>g.id===card.dataset.gameCard);if(!f)return;card.querySelector('[data-clock]').textContent=fixtureClock(f);const score=fixtureScore(f);card.querySelectorAll('[data-score]').forEach(el=>el.textContent=score[+el.dataset.score]);card.classList.toggle('is-live',f.status==='live');card.querySelectorAll('.score-school').forEach((el,i)=>el.classList.toggle('winner',f.winner===[f.away,f.home][i]));});const progress=$('season').querySelector('.season-progress');if(progress&&progress.firstChild)progress.firstChild.textContent=leagueProgress+' ';}
async function watchSeasonGame(id){const f=league.games.find(g=>g.id===id);if(!f||f.status==='bye')return;if(f.status==='scheduled'){clearTimeout(timer);running=false;game=null;cursor=0;if(!leaguePreviewMatchup)leaguePreviewMatchup=structuredClone(matchup);matchup=[leagueTeam(f.away),leagueTeam(f.home)];leagueWatch={seasonId:league.id,fixtureId:id};view('gamecast');$('latest').innerHTML='<div class="type">UPCOMING MATCHUP</div><p>Return to the league scoreboard to simulate this week with every other scheduled game.</p>';$('recent-feed').innerHTML='<div class="empty">Awaiting kickoff.</div>';render();renderLeagueWatchRibbon();return;}const full=hydrateSeasonResult(await seasonDB('results','get',`${league.id}:${id}`));if(!full)throw new Error('Stored game could not be loaded.');clearTimeout(timer);running=false;game=full;leagueWatch={seasonId:league.id,fixtureId:id};cursor=f.status==='final'?full.events.length:f.cursor||0;view('gamecast');render();renderLeagueWatchRibbon();}
function renderLeagueWatchRibbon(){const ribbon=$('season-game-ribbon');if(!ribbon)return;ribbon.classList.toggle('hidden',!leagueWatch);if(!leagueWatch)return;ribbon.innerHTML=`<button id="back-to-league" class="small">← League scoreboard</button><span>${esc(league.name)}</span><select id="switch-league-game" aria-label="Switch league game">${league.games.filter(g=>g.status!=='bye').map(g=>seasonOption(g.id,`${leagueTeam(g.away).name} vs ${leagueTeam(g.home).name} · ${g.phase==='regular'?'Week '+g.week:'Round '+g.round}`,leagueWatch.fixtureId)).join('')}</select>`;$('back-to-league').onclick=()=>{seasonTab='scoreboard';view('season');};$('switch-league-game').onchange=e=>watchSeasonGame(e.target.value);$('start').textContent=leagueBusy?(leaguePaused?'▶ RESUME LEAGUE':'Ⅱ PAUSE LEAGUE'):'← LEAGUE SCOREBOARD';$('finish').disabled=!leagueBusy;$('finish').textContent='Finish league batch ↗';const fixture=league.games.find(g=>g.id===leagueWatch.fixtureId);$('game-status').textContent=fixture?.status==='final'?'FINAL':fixture?.status==='scheduled'?'UPCOMING MATCHUP':leagueBusy?(leaguePaused?'LEAGUE PAUSED':'● LIVE LEAGUE'):'READY TO RESUME LEAGUE';document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',b.dataset.speed===String(leagueSpeed)));}
function syncSeasonWatch(){if(!leagueWatch||leagueWatch.seasonId!==league?.id)return;const f=league.games.find(g=>g.id===leagueWatch.fixtureId);if(!f||game?.fixtureId!==f.id)return;cursor=f.status==='final'?game.events.length:f.cursor||0;if(['gamecast','log','stats'].includes(currentView)){render();if(currentView==='log')renderLog();if(currentView==='stats')renderStats();renderLeagueWatchRibbon();}}
function detachSeasonWatch(){leagueWatch=null;if(leaguePreviewMatchup){matchup=leaguePreviewMatchup;leaguePreviewMatchup=null;}$('season-game-ribbon')?.classList.add('hidden');$('finish').textContent='Skip to final ↗';}
let seasonLogoPromise=Promise.resolve(null);
$('league-school-logo').onchange=e=>{const file=e.target.files[0];$('league-logo-clean').disabled=!file;seasonLogoPromise=file?prepareLogo(file).catch(err=>{toast(err.message);return null;}):Promise.resolve(null);};
$('league-logo-clean').onclick=()=>{seasonLogoPromise=seasonLogoPromise.then(src=>src?editLogoBackground(src):null).catch(err=>{toast(err.message);return null;});};
async function createLeagueSchool(){seasonLogoPromise=Promise.resolve(null);$('league-logo-clean').disabled=true;const dialog=$('season-team-dialog');$('league-school-form').reset();$('league-school-rating').value='75';dialog.showModal();}
$('league-school-form').onsubmit=async e=>{e.preventDefault();try{const name=$('league-school-name').value.trim(),mascot=$('league-school-mascot').value.trim(),overall=+$('league-school-rating').value;if(!name||!mascot||overall<1||overall>99)throw new Error('Enter a school, mascot, and rating from 1–99.');let t=normalizeTeam({state:selectedState,id:crypto.randomUUID(),name,mascot,overall,primary:$('league-school-primary').value,secondary:$('league-school-secondary').value});const file=$('league-school-logo').files[0];if(file){t.logo=await seasonLogoPromise;if(!t.logo)throw new Error('Please upload the logo again.');Object.assign(t,await extractLogoColors(t.logo)||{});}await db('teams','put',t);savedTeams=await db('teams','getAll');seasonDraft.teams.push({...t,division:'',tier:''});$('season-team-dialog').close();renderSeason();}catch(err){toast(err.message);}};
