 if(action==='launch'){await launchSeason();return;}
 if(action==='template'){const d=seasonDraft;const t={id:crypto.randomUUID(),state:selectedState,name:d.name||'League template',teams:structuredClone(d.teams),settings:structuredClone(d.settings),schedule:structuredClone(d.schedule),divisions:d.divisions,tiers:d.tiers};await seasonDB('templates','put',t);leagueTemplates=await seasonDB('templates','getAll');leagueMessage='League template saved.';}
 if(action.startsWith('template-load:')){const t=leagueTemplates.find(t=>t.id===action.slice(14));seasonDraft={...structuredClone(t),seed:randomSeed(),savedSelection:new Set()};seasonSetupPage=0;}
 if(action.startsWith('template-delete:')){await seasonDB('templates','delete',action.slice(16));leagueTemplates=await seasonDB('templates','getAll');}
