 if(action.startsWith('archive:')){league=await seasonDB('seasons','get',action.slice(8));detachSeasonWatch();leagueLive.clear();await prepareSeasonLogos();await restoreLeagueLive();seedDraft=null;seasonTab='scoreboard';leagueFilter='';leagueBoardPhase='auto';leagueBoardRound=0;await seasonDB('prefs','put',{id:'active',value:league.id});}
 if(action.startsWith('star:')){const id=action.slice(5);if(favorites.has(id))favorites.delete(id);else favorites.add(id);await seasonDB('prefs','put',{id:'favorites',value:[...favorites]});}
 if(action.startsWith('team-history:')){careerTeam=action.slice(13);seasonTab='career';}
 if(action==='runback'){newSeasonDraft(true);generateDraft(true);await launchSeason();await runLeagueAction('sim-all');return;}
