$('active-state').onchange=async e=>{const next=e.target.value;if(next===selectedState||!validState(next))return;if(leagueBusy){e.target.value=selectedState;toast('Finish the running league batch before switching states.');return;}if((running||(currentView==='setup'&&matchup.some(t=>t.name))||(seasonTab==='setup'&&seasonDraft?.teams.length))&&!confirm('Switch states? Unsaved team edits and league setup will be cleared. Saved teams, seasons, and records are kept.')){e.target.value=selectedState;return;}
 clearTimeout(timer);running=false;detachSeasonWatch();game=null;cursor=0;selectedState=next;try{localStorage.setItem('friday-night-state',next);}catch{}savedTeams=await db('teams','getAll');const teams=stateTeams();matchup=[teams[0]?structuredClone(teams[0]):blankTeam(),teams[1]?structuredClone(teams[1]):blankTeam()];historyTeamId='';historyPage=0;seasonDraft=null;seedDraft=null;careerTeam='';leagueFilter='';leagueDivision='';leagueTier='';leagueBoardPhase='auto';leagueBoardRound=0;leaguePage=0;leagueLive.clear();leagueArchive=await seasonDB('seasons','getAll');league=leagueArchive.filter(s=>leagueState(s)===selectedState).sort((a,b)=>b.created.localeCompare(a.created))[0]||null;if(league){await prepareSeasonLogos();await restoreLeagueLive();}seasonTab=league?'scoreboard':'setup';leagueMessage='';$('latest').innerHTML='<div class="type">Ready for kickoff.</div><p>Select teams from your state to build a matchup.</p>';$('recent-feed').innerHTML='<div class="empty">Kickoff is next.</div>';renderStateSelector();render();view(currentView==='season'?'season':currentView==='history'?'history':'setup');};
